/* ------------------------------------------------------------------ */
/* Engine output plumbing                                             */
/* ------------------------------------------------------------------ */

/* fetch a property of the global object (agent, ui, ...) */
static JSValue get_global_obj(JSContext *ctx, const char *name)
{
    JSValue g = JS_GetGlobalObject(ctx);
    return JS_GetPropertyStr(ctx, g, name);
}

static void serial_write_func(void *opaque, const void *buf, size_t buf_len)
{
    (void)opaque;
    if (gSerialEnabled)
        Serial.write(reinterpret_cast<const uint8_t *>(buf), buf_len);
}

static int64_t get_time_ms(void)
{
    return (int64_t)millis();
}

static int64_t get_date_ms(void)
{
    return (int64_t)millis();
}

static void dump_error(JSContext *ctx)
{
    JSValue obj = JS_GetException(ctx);
    JS_PrintValueF(ctx, obj, JS_DUMP_LONG);
    Serial.write("\n");
}

/* ------------------------------------------------------------------ */
/* REPL glue                                                           */
/* ------------------------------------------------------------------ */

JSValue js_print(JSContext *ctx, JSValue *this_val, int argc, JSValue *argv)
{
    int i;
    for (i = 0; i < argc; i++) {
        if (i != 0)
            Serial.write(' ');
        if (JS_IsString(ctx, argv[i])) {
            JSCStringBuf buf;
            size_t len;
            const char *str = JS_ToCStringLen(ctx, &len, argv[i], &buf);
            Serial.write(reinterpret_cast<const uint8_t *>(str), len);
        } else {
            JS_PrintValueF(ctx, argv[i], JS_DUMP_LONG);
        }
    }
    Serial.write('\n');
    return JS_UNDEFINED;
}

JSValue js_gc(JSContext *ctx, JSValue *this_val, int argc, JSValue *argv)
{
    JS_GC(ctx);
    return JS_UNDEFINED;
}

JSValue js_date_constructor(JSContext *ctx, JSValue *this_val,
                            int argc, JSValue *argv)
{
    double val;
    argc &= ~FRAME_CF_CTOR;
    if (argc == 0) {
        val = get_date_ms();
    } else if (argc == 1 && JS_IsNumber(ctx, argv[0])) {
        if (JS_ToNumber(ctx, &val, argv[0]))
            return JS_EXCEPTION;
    } else {
        return JS_ThrowTypeError(ctx, "unsupported Date() parameter");
    }
    return JS_NewDate(ctx, val);
}

JSValue js_date_now(JSContext *ctx, JSValue *this_val, int argc, JSValue *argv)
{
    return JS_NewInt64(ctx, get_date_ms());
}

JSValue js_performance_now(JSContext *ctx, JSValue *this_val, int argc, JSValue *argv)
{
    return JS_NewInt64(ctx, get_time_ms());
}

/* load a script file from the SD card */
JSValue js_load(JSContext *ctx, JSValue *this_val, int argc, JSValue *argv)
{
    JSCStringBuf buf_str;
    const char *filename;
    JSValue ret;
    fs::File f;
    int buf_len;

    if (argc < 1)
        return JS_ThrowTypeError(ctx, "load(): missing filename");
    filename = JS_ToCString(ctx, argv[0], &buf_str);
    if (!filename)
        return JS_EXCEPTION;
    f = SD.open(filename, FILE_READ);
    if (!f.isDirectory() && f) {
        buf_len = (int)f.size();
        uint8_t *buf = (uint8_t *)malloc(buf_len + 1);
        if (!buf) {
            f.close();
            return JS_ThrowOutOfMemory(ctx);
        }
        if (f.read(buf, (size_t)buf_len) != (size_t)buf_len) {
            free(buf);
            f.close();
            return JS_ThrowInternalError(ctx, "load(): short read on %s", filename);
        }
        buf[buf_len] = '\0';
        f.close();
        ret = JS_Eval(ctx, (const char *)buf, (size_t)buf_len, filename, JS_EVAL_STRIP_COL);
        free(buf);
    } else {
        if (f)
            f.close();
        return JS_ThrowInternalError(ctx, "load(): cannot open '%s'", filename);
    }
    return ret;
}

/* ------------------------------------------------------------------ */
/* Timers (embedded equivalent of the REPL's setTimeout/clearTimeout) */
/* ------------------------------------------------------------------ */

struct JSTimer {
    bool allocated = false;
    JSGCRef func;
    int64_t timeout; /* ms */
};
#define MAX_TIMERS 16
static JSTimer s_timer_list[MAX_TIMERS];

JSValue js_setTimeout(JSContext *ctx, JSValue *this_val, int argc, JSValue *argv)
{
    JSTimer *th;
    int delay, i;
    JSValue *pfunc;

    if (!JS_IsFunction(ctx, argv[0]))
        return JS_ThrowTypeError(ctx, "not a function");
    if (JS_ToInt32(ctx, &delay, argv[1]))
        return JS_EXCEPTION;
    for (i = 0; i < MAX_TIMERS; i++) {
        th = &s_timer_list[i];
        if (!th->allocated) {
            pfunc = JS_AddGCRef(ctx, &th->func);
            *pfunc = argv[0];
            th->timeout = get_time_ms() + delay;
            th->allocated = true;
            return JS_NewInt32(ctx, i);
        }
    }
    return JS_ThrowInternalError(ctx, "too many timers");
}

JSValue js_clearTimeout(JSContext *ctx, JSValue *this_val, int argc, JSValue *argv)
{
    int timer_id;
    JSTimer *th;

    if (JS_ToInt32(ctx, &timer_id, argv[0]))
        return JS_EXCEPTION;
    if (timer_id >= 0 && timer_id < MAX_TIMERS) {
        th = &s_timer_list[timer_id];
        if (th->allocated) {
            JS_DeleteGCRef(ctx, &th->func);
            th->allocated = false;
        }
    }
    return JS_UNDEFINED;
}

static void run_timers(JSContext *ctx)
{
    int i;
    JSTimer *th;
    int64_t cur_time = get_time_ms();

    for (i = 0; i < MAX_TIMERS; i++) {
        th = &s_timer_list[i];
        if (th->allocated && th->timeout <= cur_time) {
            JSValue ret;
            if (JS_StackCheck(ctx, 2)) {
                dump_error(ctx);
                JSValue id = JS_NewInt32(ctx, i);
                js_clearTimeout(ctx, NULL, 1, &id);
                continue;
            }
            JS_PushArg(ctx, th->func.val); /* func */
            JS_PushArg(ctx, JS_NULL);      /* this */
            JS_DeleteGCRef(ctx, &th->func);
            th->allocated = false;
            ret = JS_Call(ctx, 0);
            if (JS_IsException(ret)) {
                dump_error(ctx);
            }
        }
    }
}

/* ------------------------------------------------------------------ */
/* Plugin registry                                                     */
/* ------------------------------------------------------------------ */

#define MAX_PLUGINS 8

struct PluginSlot {
    bool used = false;
    JSGCRef ref;
};
static PluginSlot s_plugins[MAX_PLUGINS];
static int s_plugin_count = 0;
static int32_t s_epoch = 0;

/* per-plugin configuration persisted to the SD card (/plugins.json) */
static const char *kPluginConfigPath = "/plugins.json";
static JsonDocument s_pluginConfig;       /* { "plugins": { "<name>": { enabled, options } } } */
static bool s_pluginConfigDirty = false;
static char s_currentPluginFile[64] = {0}; /* name of the file being evaluated */

static bool plugin_config_entry_is_new(JsonObject root, const char *name)
{
    return !root[name].is<JsonObject>();
}

/* "/plugins/example.js" -> "example"; also just "example.js" -> "example" */
static void plugin_name_simple(const String &path, char *out, size_t cap)
{
    String name = path;
    int slash = name.lastIndexOf('/');
    if (slash >= 0)
        name = name.substring(slash + 1);
    if (name.endsWith(".js"))
        name = name.substring(0, name.length() - 3);
    strncpy(out, name.c_str(), cap - 1);
    out[cap - 1] = '\0';
}

/* serialize a JS value to a JSON string (used to store plugin options) */
static bool js_value_to_json(JSContext *ctx, JSValue val, char *out, size_t cap)
{
    JSGCRef val_ref;
    JS_PUSH_VALUE(ctx, val);
    JSValue argv[1];
    argv[0] = val;
    JSValue ret = js_json_stringify(ctx, NULL, 1, argv);
    JS_POP_VALUE(ctx, val);
    if (JS_IsException(ret))
        return false;
    JSCStringBuf b;
    const char *s = JS_ToCString(ctx, ret, &b);
    if (!s)
        return false;
    strncpy(out, s, cap > 0 ? cap - 1 : 0);
    if (cap > 0)
        out[cap - 1] = '\0';
    return true;
}

static void load_plugin_config()
{
    s_pluginConfig.clear();
    if (!SD.exists(kPluginConfigPath)) {
        s_pluginConfigDirty = true; /* plugin list will be created on save */
        return;
    }
    fs::File f = SD.open(kPluginConfigPath, FILE_READ);
    if (!f) {
        s_pluginConfigDirty = true;
        return;
    }
    deserializeJson(s_pluginConfig, f);
    f.close();
}

static void save_plugin_config()
{
    if (!s_pluginConfigDirty)
        return;
    fs::File f = SD.open(kPluginConfigPath, FILE_WRITE);
    if (!f) {
        SERIAL_PRINTF("[plugins] cannot write %s\n", kPluginConfigPath);
        return;
    }
    serializeJsonPretty(s_pluginConfig, f);
    f.close();
    s_pluginConfigDirty = false;
    SERIAL_PRINTF("[plugins] saved %s\n", kPluginConfigPath);
}

/* ------------------------------------------------------------------ */
/* Plugin construction: enabled flag + options from /plugins.json      */
/* ------------------------------------------------------------------ */

static void set_plugin_options_prop(JSContext *ctx, JSValue *this_val,
                                    const JsonObject &entry)
{
    if (!entry["options"].is<JsonObject>())
        return;
    char buf[768];
    size_t n = serializeJson(entry["options"], buf, sizeof(buf));
    (void)n;
    JSValue arg = JS_NewString(ctx, buf);
    JSGCRef arg_ref;
    JS_PUSH_VALUE(ctx, arg);
    JSValue arg_dup = arg;
    JSValue opts = js_json_parse(ctx, NULL, 1, &arg_dup);
    JS_POP_VALUE(ctx, arg);
    if (JS_IsException(opts))
        return;
    JSGCRef opts_ref;
    JS_PUSH_VALUE(ctx, opts);
    JS_SetPropertyStr(ctx, *this_val, "options", opts);
    JS_POP_VALUE(ctx, opts);
}

/* mquickjs does not export JS_IsObject; treat everything that is not
   undefined/null/exception as an object-like value */
static bool js_is_object_like(JSValue v)
{
    return !JS_IsNull(v) && !JS_IsUndefined(v) && !JS_IsException(v);
}

JSValue js_pwn_plugin(JSContext *ctx, JSValue *this_val, int argc, JSValue *argv)
{
    /* new Plugin({...}) */
    argc &= ~FRAME_CF_CTOR;
    if (argc < 1)
        return JS_ThrowTypeError(ctx, "Plugin() requires an options object");

    JSValue options = argv[0];

    /* ------------------------------------------------ */
    /* resolve plugin name from the current script file  */
    /* ------------------------------------------------ */
    char pluginName[32];
    if (s_currentPluginFile[0])
        plugin_name_simple(String(s_currentPluginFile), pluginName, sizeof(pluginName));
    else
        snprintf(pluginName, sizeof(pluginName), "plugin%u", (unsigned)s_plugin_count);

    /* ------------------------------------------------ */
    /* read declared defaults (__defaults__ or options)  */
    /* ------------------------------------------------ */
    JSValue defs = JS_GetPropertyStr(ctx, options, "__defaults__");
    JSValue defOpts = JS_GetPropertyStr(ctx, options, "options");
    JSValue declOptions = JS_UNDEFINED;
    if (js_is_object_like(defs)) {
        declOptions = JS_GetPropertyStr(ctx, defs, "options");
        if (!js_is_object_like(declOptions))
            declOptions = JS_UNDEFINED;
    } else if (js_is_object_like(defOpts)) {
        declOptions = defOpts;
    }

    /* ------------------------------------------------ */
    /* update /plugins.json entry for this plugin        */
    /* ------------------------------------------------ */
    JsonObject root = s_pluginConfig["plugins"].to<JsonObject>();
    bool isNew = plugin_config_entry_is_new(root, pluginName);
    JsonObject entry = root[pluginName].to<JsonObject>();
    if (isNew) {
        entry["enabled"] = false; /* plugins start disabled */
        if (!JS_IsUndefined(declOptions)) {
            char buf[768];
            if (js_value_to_json(ctx, declOptions, buf, sizeof(buf))) {
                JsonDocument tmp;
                if (deserializeJson(tmp, buf) == DeserializationError::Ok) {
                    JsonObject opt = entry["options"].to<JsonObject>();
                    for (JsonPair kv : tmp.as<JsonObject>())
                        opt[kv.key()] = kv.value();
                } else {
                    entry.remove("options");
                }
            }
        }
        s_pluginConfigDirty = true;
        SERIAL_PRINTF("[plugins] new plugin '%s' added to %s\n",
                      pluginName, kPluginConfigPath);
    }

    bool enabled = entry["enabled"] | false;
    SERIAL_PRINTF("[plugins] plugin '%s' %s\n",
                  pluginName, enabled ? "enabled" : "disabled");

    /* merge config options back into the instance so hooks can read
       this.options.* ; fall back to the declared defaults object */
    if (entry["options"].is<JsonObject>()) {
        set_plugin_options_prop(ctx, this_val, entry);
    } else if (js_is_object_like(declOptions)) {
        JSGCRef declOptions_ref;
        JS_PUSH_VALUE(ctx, declOptions);
        JS_SetPropertyStr(ctx, *this_val, "options", declOptions);
        JS_POP_VALUE(ctx, declOptions);
    }

    /* disabled plugins are not registered: no hooks, no on_loaded */
    if (!enabled)
        return *this_val;

    /* copy own properties from the options object onto the instance */
    static const char *const kKeys[] = {
        "__author__", "__version__", "__license__", "__description__",
        "on_loaded", "on_unload", "on_ui_setup", "on_ui_update",
        "on_ready", "on_epoch", "on_channel_hop",
        "on_ap_detected", "on_wifi_update",
        "on_handshake", "on_deauthentication",
        "on_peer_detected", "on_peer_encounter", "on_peer_lost", "on_friend",
    };
    for (size_t k = 0; k < sizeof(kKeys) / sizeof(kKeys[0]); k++) {
        JSValue v = JS_GetPropertyStr(ctx, options, kKeys[k]);
        if (JS_IsException(v))
            return JS_EXCEPTION;
        if (!JS_IsUndefined(v) && !JS_IsNull(v)) {
            JSValue ret = JS_SetPropertyStr(ctx, *this_val, kKeys[k], v);
            if (JS_IsException(ret))
                return ret;
        }
    }

    if (s_plugin_count >= MAX_PLUGINS)
        return JS_ThrowInternalError(ctx, "too many plugins");
    JSValue *slot = JS_AddGCRef(ctx, &s_plugins[s_plugin_count].ref);
    *slot = *this_val;
    s_plugins[s_plugin_count].used = true;
    s_plugin_count++;

    /* pwnagotchi semantics: on_loaded(agent) fires as soon as the plugin is
       created, before any firmware event is dispatched. */
    JSValue loaded = JS_GetPropertyStr(ctx, *this_val, "on_loaded");
    if (JS_IsException(loaded)) {
        dump_error(ctx);
    } else if (JS_IsFunction(ctx, loaded)) {
        JSValue agent = get_global_obj(ctx, "agent");
        if (JS_StackCheck(ctx, 3)) {
            dump_error(ctx);
        } else {
            JS_PushArg(ctx, agent);
            JS_PushArg(ctx, loaded);
            JS_PushArg(ctx, *this_val);
            JSValue ret = JS_Call(ctx, 1);
            if (JS_IsException(ret))
                dump_error(ctx);
        }
    }
    return *this_val;
}

