JSValue js_pwn_agent_get_identity(JSContext *ctx, JSValue *this_val, int argc, JSValue *argv)
{
    const char *name = "pentagotchi";
    if (gInstance)
        name = gInstance->config().name;
    return JS_NewString(ctx, name);
}

JSValue js_pwn_agent_get_epoch(JSContext *ctx, JSValue *this_val, int argc, JSValue *argv)
{
    return JS_NewInt32(ctx, s_epoch);
}

JSValue js_pwn_agent_get_config(JSContext *ctx, JSValue *this_val, int argc, JSValue *argv)
{
    JSGCRef cfg_ref, o_ref;
    JSValue cfg;

    if (!gInstance)
        return JS_NewObject(ctx);
    const pentagotchi_config_t &c = gInstance->config();

    cfg = JS_NewObject(ctx);
    JS_PUSH_VALUE(ctx, cfg);

    JSValue o = JS_NewObject(ctx);
    JS_PUSH_VALUE(ctx, o);
#define SET_STR(tgt, key, val) do { JSValue s = JS_NewString(ctx, (val)); JSGCRef s_ref; JS_PUSH_VALUE(ctx, s); JS_SetPropertyStr(ctx, (tgt), (key), s); JS_POP_VALUE(ctx, s); } while (0)
#define SET_INT(tgt, key, val) do { JS_SetPropertyStr(ctx, (tgt), (key), JS_NewInt32(ctx, (val))); } while (0)
#define SET_BOOL(tgt, key, val) do { JS_SetPropertyStr(ctx, (tgt), (key), JS_NewBool((val))); } while (0)

    SET_STR(cfg, "name", c.name);
    SET_STR(cfg, "lang", c.lang);
    SET_BOOL(cfg, "grid_enabled", c.grid_enabled);
    SET_BOOL(cfg, "gps_enabled", c.gps_enabled);
    SET_BOOL(cfg, "deauth_enabled", c.deauth_enabled);
    SET_BOOL(cfg, "serial", c.serial);
    SET_INT(cfg, "uptime", (int32_t)gInstance->uptimeSec());
    SET_INT(cfg, "epoch", s_epoch);
    SET_INT(cfg, "handshakes", gHandshakeCount);
    SET_INT(cfg, "total_pwnd", (int32_t)gInstance->stats().total_pwnd);
    SET_INT(cfg, "total_aps", (int32_t)gInstance->stats().total_aps);

    SET_BOOL(o, "enabled", c.display.enabled);
    SET_STR(o, "rotation", c.display.rotation);
    SET_STR(o, "type", c.display.type);
    SET_STR(o, "color", c.display.color);
    JS_SetPropertyStr(ctx, cfg, "display", o);
    JS_POP_VALUE(ctx, o);

    JS_POP_VALUE(ctx, cfg);
    return cfg;
#undef SET_STR
#undef SET_INT
#undef SET_BOOL
}

