JSValue js_pwn_face_get(JSContext *ctx, JSValue *this_val, int argc, JSValue *argv, int magic)
{
    const char *s = "(-_-)";
    if (magic >= 0 && magic < (int)(sizeof(kFaces) / sizeof(kFaces[0])))
        s = kFaces[magic];
    return JS_NewString(ctx, s);
}

/* ------------------------------------------------------------------ */
/* Event dispatch                                                      */
/* ------------------------------------------------------------------ */

namespace {

struct PendingEvent {
    uint8_t used;
    pwn_event_id_t id;
    int32_t value;
    int32_t rssi;
    uint8_t mac[6];
    char str[48];
};

#define EVENT_QUEUE_SIZE 8
static PendingEvent s_queue[EVENT_QUEUE_SIZE];
static portMUX_TYPE s_queueMux = portMUX_INITIALIZER_UNLOCKED;

void build_ap_object(JSContext *ctx, const uint8_t *mac, int rssi, int channel,
                     const char *ssid, JSValue out)
{
    char macstr[18];
    if (mac) {
        macToString(mac).toCharArray(macstr, sizeof(macstr));
        JSValue s = JS_NewString(ctx, macstr);
        JSGCRef s_ref;
        JS_PUSH_VALUE(ctx, s);
        JS_SetPropertyStr(ctx, out, "bssid", s);
        JS_POP_VALUE(ctx, s);
    }
    JS_SetPropertyStr(ctx, out, "rssi", JS_NewInt32(ctx, rssi));
    JS_SetPropertyStr(ctx, out, "channel", JS_NewInt32(ctx, channel));
    if (ssid && ssid[0]) {
        JSValue s = JS_NewString(ctx, ssid);
        JSGCRef s_ref;
        JS_PUSH_VALUE(ctx, s);
        JS_SetPropertyStr(ctx, out, "ssid", s);
        JS_POP_VALUE(ctx, s);
    }
}

void build_client_object(JSContext *ctx, const uint8_t *mac, int rssi, int channel, JSValue out)
{
    if (mac) {
        char macstr[18];
        macToString(mac).toCharArray(macstr, sizeof(macstr));
        JSValue s = JS_NewString(ctx, macstr);
        JSGCRef s_ref;
        JS_PUSH_VALUE(ctx, s);
        JS_SetPropertyStr(ctx, out, "mac", s);
        JS_POP_VALUE(ctx, s);
    }
    JS_SetPropertyStr(ctx, out, "signal", JS_NewInt32(ctx, rssi));
    JS_SetPropertyStr(ctx, out, "channel", JS_NewInt32(ctx, channel));
}

void build_peer_object(JSContext *ctx, const char *name, int32_t value, int32_t rssi, JSValue out)
{
    if (name && name[0]) {
        JSValue s = JS_NewString(ctx, name);
        JSGCRef s_ref;
        JS_PUSH_VALUE(ctx, s);
        JS_SetPropertyStr(ctx, out, "identity", s);
        JS_SetPropertyStr(ctx, out, "name", s);
        JS_POP_VALUE(ctx, s);
    }
    /* fill real data from the grid when available */
    String closestFace, closestName;
    uint32_t cSession = 0, cTotal = 0;
    int cRssi = -1000;
    if (pentagotchi_grid_closest_peer(closestFace, closestName, cSession, cTotal, cRssi)) {
        if (!closestFace.isEmpty()) {
            JSValue s = JS_NewString(ctx, closestFace.c_str());
            JSGCRef s_ref;
            JS_PUSH_VALUE(ctx, s);
            JS_SetPropertyStr(ctx, out, "face", s);
            JS_POP_VALUE(ctx, s);
        }
        if (!closestName.isEmpty()) {
            JSValue s = JS_NewString(ctx, closestName.c_str());
            JSGCRef s_ref;
            JS_PUSH_VALUE(ctx, s);
            JS_SetPropertyStr(ctx, out, "name", s);
            JS_POP_VALUE(ctx, s);
        }
        JS_SetPropertyStr(ctx, out, "rssi", JS_NewInt32(ctx, cRssi));
        JS_SetPropertyStr(ctx, out, "pwnd_session", JS_NewInt32(ctx, (int32_t)cSession));
        JS_SetPropertyStr(ctx, out, "pwnd_total", JS_NewInt32(ctx, (int32_t)cTotal));
    } else {
        JS_SetPropertyStr(ctx, out, "rssi", JS_NewInt32(ctx, rssi));
    }
    JS_SetPropertyStr(ctx, out, "encounters", JS_NewInt32(ctx, value));
    return;
}

/* call on_<hook> for every plugin, passing argc argv to each instance.
   JS_Call expects the arguments pushed in reverse order (arg[n-1] ...
   arg[0]), then the function, then the 'this' object. */
void call_hooks(JSContext *ctx, const char *hook,
                int argc, JSValue *argv)
{
    for (int i = 0; i < s_plugin_count; i++) {
        PluginSlot &slot = s_plugins[i];
        if (!slot.used)
            continue;
        JSValue plugin = slot.ref.val;
        JSValue func = JS_GetPropertyStr(ctx, plugin, hook);
        if (JS_IsException(func)) {
            dump_error(ctx);
            continue;
        }
        if (!JS_IsFunction(ctx, func))
            continue;
        if (JS_StackCheck(ctx, argc + 2)) {
            dump_error(ctx);
            continue;
        }
        for (int a = argc - 1; a >= 0; a--)
            JS_PushArg(ctx, argv[a]);
        JS_PushArg(ctx, func);
        JS_PushArg(ctx, plugin);
        JSValue ret = JS_Call(ctx, argc);
        if (JS_IsException(ret)) {
            dump_error(ctx);
        }
    }
}

/* Dispatch a single event copied from the firmware bus. Builds the hook
   arguments as GC-rooted JSValues, calls every plugin's handler, then pops
   the roots. agent/ui are properties of the global object (always
   reachable), the rest are transient and must be rooted. */
void dispatch_event(JSContext *ctx, const PendingEvent &ev)
{
    JSValue agent = get_global_obj(ctx, "agent");
    JSValue ui = get_global_obj(ctx, "ui");

    JSValue args[4];
    JSGCRef args_ref[4];
    int nargs = 0;

    /* root an argument as soon as it is produced so transient objects
       (ap, client, peer, strings) survive any GC triggered while the
       argument objects are being built */
    auto add_arg = [&](JSValue v) {
        args[nargs] = v;
        *JS_PushGCRef(ctx, &args_ref[nargs]) = v;
        nargs++;
    };

    const char *hook = "";
    switch (ev.id) {
    case PWN_EVENT_BOOT:
        hook = "on_ready";
        add_arg(agent);
        break;
    case PWN_EVENT_SCAN_CYCLE:
        hook = "on_epoch";
        s_epoch++;
        add_arg(agent);
        add_arg(JS_NewInt32(ctx, ev.value > 0 ? ev.value : readWifiChannel()));
        break;
    case PWN_EVENT_CHANNEL_CHANGED:
        hook = "on_channel_hop";
        add_arg(agent);
        add_arg(JS_NewInt32(ctx, ev.value));
        break;
    case PWN_EVENT_AP_DETECTED:
    case PWN_EVENT_DEAUTH_SENT: {
        hook = (ev.id == PWN_EVENT_AP_DETECTED) ? "on_ap_detected" : "on_deauthentication";
        JSValue ap = JS_NewObject(ctx);
        add_arg(ap);
        const char *ssid = nullptr;
        if (ev.id == PWN_EVENT_AP_DETECTED) {
            /* look up ssid for the new beacon */
            BeaconEntry probe;
            memset(&probe, 0, sizeof(probe));
            if (ev.mac) memcpy(probe.mac, ev.mac, 6);
            portENTER_CRITICAL(&gRadioMux);
            auto it = gRegisteredBeacons.find(probe);
            if (it != gRegisteredBeacons.end())
                ssid = it->ssid;
            portEXIT_CRITICAL(&gRadioMux);
        }
        build_ap_object(ctx, ev.mac, ev.rssi, ev.value, ssid, ap);
        if (ev.id == PWN_EVENT_DEAUTH_SENT) {
            JSValue client = JS_NewObject(ctx);
            add_arg(client);
            build_client_object(ctx, ev.mac, ev.rssi, ev.value, client);
        }
        break;
    }
    case PWN_EVENT_HANDSHAKE: {
        hook = "on_handshake";
        JSValue ap = JS_NewObject(ctx);
        add_arg(ap);
        build_ap_object(ctx, nullptr, 0, readWifiChannel(), nullptr, ap);
        JSValue client = JS_NewObject(ctx);
        add_arg(client);
        build_client_object(ctx, nullptr, 0, 0, client);
        char filename[64];
        if (!gLastPwndName.isEmpty()) {
            String macnum = gLastPwndName;
            macnum.replace(":", "");
            snprintf(filename, sizeof(filename), "/Handshakes/HS_%s.pcap", macnum.c_str());
        } else {
            snprintf(filename, sizeof(filename), "/Handshakes/HS_%d.pcap", gHandshakeCount);
        }
        add_arg(JS_NewString(ctx, filename));
        break;
    }
    case PWN_EVENT_PEER_DETECTED:
    case PWN_EVENT_PEER_ENCOUNTER:
    case PWN_EVENT_PEER_GONE:
    case PWN_EVENT_FRIEND: {
        const char *peer_hooks[] = { "on_peer_detected", "on_peer_encounter",
                                     "on_peer_lost", "on_friend" };
        hook = peer_hooks[ev.id - PWN_EVENT_PEER_DETECTED];
        JSValue peer = JS_NewObject(ctx);
        add_arg(peer);
        build_peer_object(ctx, ev.str, ev.value, ev.rssi, peer);
        break;
    }
    case PWN_EVENT_MOOD_CHANGED:
        hook = "on_ui_update";
        add_arg(ui);
        break;
    case PWN_EVENT_STATS_CLEARED:
    default:
        hook = "";
        break;
    }

    if (hook[0] != '\0')
        call_hooks(ctx, hook, nargs, args);

    /* pop roots in reverse order */
    for (int i = nargs - 1; i >= 0; i--)
        JS_PopGCRef(ctx, &args_ref[i]);
}

} // namespace

/* ------------------------------------------------------------------ */
/* Firmware event bus -> queue -> poll()                              */
/* ------------------------------------------------------------------ */

static void plugins_on_event(const pwn_event_t *ev)
{
    if (!ev)
        return;
    portENTER_CRITICAL(&s_queueMux);
    for (int i = 0; i < EVENT_QUEUE_SIZE; i++) {
        PendingEvent *pe = &s_queue[i];
        if (!pe->used) {
            memset(pe, 0, sizeof(*pe));
            pe->used = 1;
            pe->id = ev->id;
            pe->value = ev->value;
            pe->rssi = ev->rssi;
            if (ev->mac) memcpy(pe->mac, ev->mac, 6);
            if (ev->str) {
                strncpy(pe->str, ev->str, sizeof(pe->str) - 1);
                pe->str[sizeof(pe->str) - 1] = '\0';
            }
            break;
        }
    }
    portEXIT_CRITICAL(&s_queueMux);
}

/* ------------------------------------------------------------------ */
/* PentagotchiPlugins implementation                                  */
/* ------------------------------------------------------------------ */

void PentagotchiPlugins::begin()
{
    if (ctx_)
        return;

    const size_t heapSize = 1024 * 1024; /* plugins run in PSRAM */
    size_t allocSize = heapSize + 16;
    uint8_t *heap = nullptr;
    heap = (uint8_t *)heap_caps_aligned_alloc(16, allocSize, MALLOC_CAP_SPIRAM);
    if (!heap) {
        heap = (uint8_t *)heap_caps_aligned_alloc(16, allocSize, MALLOC_CAP_8BIT);
    }
    if (!heap) {
        SERIAL_PRINTLN("[plugins] failed to allocate JS heap");
        return;
    }
    heap_ = heap;
    heapAllocated_ = 1;

    JSContext *ctx = JS_NewContext2(heap, heapSize, &pentagotchi_stdlib, 0);
    if (!ctx) {
        heap_caps_free(heap);
        heap_ = nullptr;
        heapAllocated_ = 0;
        SERIAL_PRINTLN("[plugins] JS context init failed");
        return;
    }
    ctx_ = ctx;

    JS_SetLogFunc(ctx, serial_write_func);
    JS_SetContextOpaque(ctx, gInstance);

    pwn_events_subscribe(PWN_EVENT_BOOT, plugins_on_event, "plugins_boot");
    pwn_events_subscribe(PWN_EVENT_SCAN_CYCLE, plugins_on_event, "plugins_scan");
    pwn_events_subscribe(PWN_EVENT_CHANNEL_CHANGED, plugins_on_event, "plugins_ch");
    pwn_events_subscribe(PWN_EVENT_AP_DETECTED, plugins_on_event, "plugins_ap");
    pwn_events_subscribe(PWN_EVENT_HANDSHAKE, plugins_on_event, "plugins_hs");
    pwn_events_subscribe(PWN_EVENT_DEAUTH_SENT, plugins_on_event, "plugins_deauth");
    pwn_events_subscribe(PWN_EVENT_PEER_DETECTED, plugins_on_event, "plugins_peer");
    pwn_events_subscribe(PWN_EVENT_PEER_ENCOUNTER, plugins_on_event, "plugins_enc");
    pwn_events_subscribe(PWN_EVENT_PEER_GONE, plugins_on_event, "plugins_gone");
    pwn_events_subscribe(PWN_EVENT_FRIEND, plugins_on_event, "plugins_friend");
    pwn_events_subscribe(PWN_EVENT_MOOD_CHANGED, plugins_on_event, "plugins_mood");

    /* Load /plugins/*.js from the SD card */
    if (!SD.exists("/plugins")) {
        if (SD.mkdir("/plugins"))
            SERIAL_PRINTF("[plugins] created /plugins/\n");
        else
            SERIAL_PRINTF("[plugins] cannot create /plugins/\n");
    }
    load_plugin_config();
    SERIAL_PRINTF("[plugins] loading /plugins/\n");
    fs::File dir = SD.open("/plugins");
    if (dir && dir.isDirectory()) {
        fs::File f = dir.openNextFile();
        while (f) {
            String name = f.name();
            if (!f.isDirectory() && name.endsWith(".js")) {
                int len = (int)f.size();
                uint8_t *buf = (uint8_t *)malloc(len + 1);
                if (buf && f.read(buf, (size_t)len) == (size_t)len) {
                    buf[len] = '\0';
                    SERIAL_PRINTF("[plugins] load %s\n", name.c_str());
                    snprintf(s_currentPluginFile, sizeof(s_currentPluginFile),
                             "%s", name.c_str());
                    JSValue v = JS_Eval(ctx, (const char *)buf, (size_t)len, name.c_str(), JS_EVAL_STRIP_COL);
                    s_currentPluginFile[0] = '\0';
                    if (JS_IsException(v)) {
                        SERIAL_PRINTF("[plugins] error in %s:\n", name.c_str());
                        dump_error(ctx);
                    }
                }
                if (buf)
                    free(buf);
                f.close();
            }
            f = dir.openNextFile();
        }
        dir.close();
    } else {
        if (dir)
            dir.close();
        SERIAL_PRINTF("[plugins] no /plugins dir on SD\n");
    }

    /* persist any newly discovered plugin entries / default options */
    save_plugin_config();

    SERIAL_PRINTF("[plugins] ready, %d plugin(s), heap %u KB\n",
                  s_plugin_count, (unsigned)(heapSize / 1024));
}

void PentagotchiPlugins::poll()
{
    if (!ctx_)
        return;

    /* Drain queued firmware events */
    for (int pass = 0; pass < EVENT_QUEUE_SIZE; pass++) {
        PendingEvent *pe = nullptr;
        portENTER_CRITICAL(&s_queueMux);
        for (int i = 0; i < EVENT_QUEUE_SIZE; i++) {
            if (s_queue[i].used) {
                pe = &s_queue[i];
                break;
            }
        }
        if (pe)
            pe->used = 0;
        portEXIT_CRITICAL(&s_queueMux);

        if (!pe)
            break;
        dispatch_event((JSContext *)ctx_, *pe);
    }

    run_timers((JSContext *)ctx_);
}

void PentagotchiPlugins::unloadAll()
{
    if (!ctx_)
        return;
    JSContext *ctx = (JSContext *)ctx_;
    for (int i = 0; i < s_plugin_count; i++) {
        if (s_plugins[i].used)
            JS_DeleteGCRef(ctx, &s_plugins[i].ref);
        s_plugins[i].used = false;
    }
    s_plugin_count = 0;
    for (int i = 0; i < MAX_TIMERS; i++) {
        if (s_timer_list[i].allocated) {
            JS_DeleteGCRef(ctx, &s_timer_list[i].func);
            s_timer_list[i].allocated = false;
        }
    }
    JS_FreeContext(ctx);
    ctx_ = nullptr;
    if (heap_ && heapAllocated_) {
        heap_caps_free(heap_);
        heap_ = nullptr;
        heapAllocated_ = 0;
    }
}

PentagotchiPlugins gPlugins;